import sys; sys.path.insert(0, "Tools/prd_ledger/77")
from _lib import c, table, save

c(1, "header lines 1-6; §2.1; §2.1 table (verbatim); §2.2 table (verbatim); §2.2 bullets", "positioning", "Habit Tracker: Streak-Free / Momentumly (App Store ID 6737206675) by Beaucode Ventures UG, Germany (Beaucode.Momentumly), Productivity / Health & Fitness, first release 2024-12-18, current 3.0.17 (2026-09-08), iOS 17+, 10 localisations, US public 37 ratings mean 4.8 — 'the first habit tracker without streaks': a momentum/points score in place of a streak (missing a day reduces a score rather than resetting it), streak still visible alongside, weekday scheduling, line graphs, month/week/day overview, calendar, per-habit widget, a Focus tab, reminders, Apple Health, onboarding, gamification (acorns, a squirrel, foxes, achievements, badges, a Habit Forest from v3.0). Naming: Store title 'Habit Tracker: Streak-Free', bundle 'Momentumly', reviewers use both; the paid tier reaches users under five names. Capability table (verbatim): " + table("## 2.1 What the product is", 0) + " || listing (verbatim): " + table("## 2.2 The listed model", 0), "free download; one-habit free tier; premium under three product names", "mixed", "71 reviews, 28 storefronts, 2025-01-10 → 2026-09-05, mean 4.31★; 5★ 50 (70.42%), 1★ 6 (8.45%); 241 code assignments (3.39/review); 17 non-English (23.9%)", "none", "header", "app-specific", ["12893716000", "13042199479"], "", "small corpus, 20 months")

c(2, "How to read this; Eight warnings 1, 2, 3, 4, 7, 8; §1.1 table (verbatim); §1.2 table (verbatim); §1.3 table (verbatim); §1.4; §1.5; §1.6; §1.7 table (verbatim); §1.9", "data-caveat", "Method and limits: 71 reviews read individually in the original language, hand-coded (78 codes in 12 families, all used; 19 unions), 30 pre-write checks incl. 14 semantic re-derivations from text, verify-after-write; no duplicates, no repeat authors, no edits; one review = 1.41% so the spec's bands cannot discriminate (4 reviews already 'High-priority') — every headline carries a Wilson 95% CI, and 'where a band and an interval disagree, trust the interval'; no storefront reaches 50 (de 17, in 10, us 10) — no standalone country claims; 14 of 71 (19.72%) are content-free 5★ ('Love it') — excluding them: mean 4.31 → 4.14★, money-negative 19.72% → 24.56%, concept-positive 26.76% → 33.33% (verbatim) " + table("## 1.7 Counting and segment rates", 0) + "; only 4 reviewers state they paid (+1 implied) — no conversion, renewal, refund or churn rate; Apple publishes no release before v2.6.4 (2025-09-29) so 36 of 71 cannot be tied to a release; 10 SKUs carry no periods so the report cannot say which are subscriptions; 2 of 21 months have zero reviews.", "n/a", "mixed", "71/71 read; 78 codes; 241 assignments; 30 checks; low-info 14 (19.72%)", "none", "method", "generalisable", ["12893716000"], "", "")

c(3, "Warning 6; §1.6.5", "data-caveat", "Selection bias quantified: 71 text reviews sit on a public base of 339 ratings across the same 28 storefronts — ratings-weighted public mean 4.58★ vs corpus 4.31★ (gap −0.27); 268 people rated without writing; every complaint share is a share of people who chose to write.", "n/a", "mixed", "339 public ratings vs 71 text; 4.58 vs 4.31", "none", "method", "generalisable", ["12893716000"], "", "")

c(4, "§0.1; §0.1 table (verbatim); §8.4", "positioning", "The concept works and nobody argues with it: 19 of 71 (26.76%, Wilson CI 17.9–38.1%) praise the no-streak / momentum model by name as the reason the app works, mean 4.89★ — not one below 4★ (17 5★, 2 4★); zero negative reactions to the thesis across 20 months, 28 storefronts, 6 languages (verbatim): " + table("## 0.1 The concept works", 0) + " — 'I used to drop habits the second I missed a day — all because of streak pressure. Momentumly flipped that for me'; 'removes all the frustration of having to start over from zero. It takes the 2-day rule even further'; 'motivates me to get things done but without the feeling of punishment when life gets in the way'; positioning does not need work.", "momentum score instead of streak; streak still visible", "praise", "19 / 26.76% / CI 17.9–38.1% / mean 4.89★ / 0 below 4★; ex-low-info 33.33%", "build-free", "High-priority", "generalisable", ["12893716000", "13042199479", "12753284542", "12756758711", "14237526621", "13634096636", "14331668442", "12809333699"], "", "")

c(5, "§0.1 (outcomes)", "insight", "11 of 71 (15.49%) report a real outcome, mean 5.00★ with none below 5★: 5 say this is the first tracker that stuck, 3 name a specific behaviour that changed (stretching; reading + stretching; healthy habits), 6 report improved consistency.", "n/a", "praise", "11 / 15.49% / mean 5.00", "none", "High-priority", "generalisable", ["12806969276", "12905347299", "13019604470", "12753284542", "13809152355", "12799674597", "14237526621"], "", "")

c(6, "§0.2; §0.2 table (verbatim)", "monetization", "The entire negative story is the free/paid boundary: 14 of 71 (19.72%, CI 12.1–30.4%) carry a monetization objection, mean 2.71★; the rest of the negative corpus is small — 5 defects (7.04%), 7 usability-friction (9.86%); of 6 one-star reviews 5 are monetization and nothing else, the sixth a comprehension failure ('Daily habits, tick mark not available'); zero 1★ report a crash or data problem as primary complaint. One-star register (verbatim): " + table("## 0.2 The entire negative story", 0), "one-habit free tier; premium for most features", "1★-burst", "14 / 19.72% / CI 12.1–30.4% / mean 2.71★; 5 of 6 1★ money-only", "product-rule", "High-priority", "generalisable", ["13064284382", "13200826254", "13277885578", "13307114320", "13340807598", "13349206242"], "", "")

c(7, "§0.3; §0.3 table (verbatim); §2.3; §8.1; §0.11 #1", "product-rule", "The free tier is one habit — and the Store listing never says so: three reviewers on three storefronts across ten months independently state the number (verbatim) " + table("## 0.3 The free tier is one habit", 0) + " — mean 2.33★; a fourth objects without the number ('I think we should get unlimited habit without paying', 3★) → cap objections 4 of 71 (5.63%, CI 2.2–13.6%), mean 2.50★; the App Store description states no habit-count limit anywhere ('helps you build your new habit' — singular); two say in as many words the boundary surprised them (MON_UNEXPECTED 2, 2.82%, mean 1.50★: 'What's the point of making a free app if it's unfunctional unless you buy a premium plan', 1★; 'Ich hatte erwartet, dass mehrere Gewohnheiten frei sind', 2★). 'A one-habit free tier is a defensible business decision. Not disclosing it is a separate, cheaper-to-fix problem, and it is the one the corpus actually punishes.'", "free = 1 habit, undisclosed", "blocked-conversion", "cap stated 3 (mean 2.33★); cap objection 4 / 5.63% / CI 2.2–13.6% / 2.50★; MON_UNEXPECTED 2 / 1.50★", "product-rule", "High-priority", "generalisable", ["13349206242", "14080954809", "14355567891", "14209508686", "13307114320"], "", "")

c(8, "§0.4; §0.4 table (verbatim); §2.2 SKU table (verbatim); §1.6.7; §0.11 #2; §0.11 #3", "monetization", "The paywall's shape is externally corroborated — and confusing: 10 IAP SKUs $2.99–$29.99 under three product names, not one showing a billing period (verbatim) " + table("## 0.4 The paywall", 0) + "; the description's only monetization paragraph is headed 'Premium Subscription' with auto-renewal boilerplate — no price, no tier, no trial, no one-time option. Consequences in the text: nobody can tell whether a one-time purchase exists — 'I've subscribed for the lifetime version' (br 2★, 2025-04-17) vs 'there is no possibility to get a lifetime version of subscription' (ro 2★, 2025-05-13, the review's entire content) vs praise for 'The one time purchase rather than a subscription model' (mx 5★, 2026-04-10); no trial and someone asked ('there should be somewhat of a free trial because you can't really explore the app', bg 4★); three product names reach users as three things ('premium', 'Premium Abo', 'the pro subscription', 'premium plan', 'Momentumly Plus').", "10 SKUs, 3 names, no periods; lifetime existence contradicted", "blocked-conversion", "10 SKUs $2.99–$29.99; lifetime contradiction 3 reviews over 12 months; trial request 1", "must-have", "High-priority", "generalisable", ["12552768633", "12652787691", "13941527190", "12530006457"], "", "")

c(9, "§0.5; §0.5 table (verbatim); §7.2", "timeline", "The one-star episode: all 6 one-star reviews fall between 2025-08-26 and 2025-11-03; the 32 reviews before contain zero 1★, the 28 after contain zero (verbatim) " + table("## 0.5 The one-star episode", 0) + " — the window opens with the only reliability regression ('now we have reached a point with the new update, where the app can't even open without crashing', dk 1★) then runs through five consecutive monetization one-stars; it closes seven days before v3.0 shipped (2025-11-10); the corpus cannot say why it ended — no evidence attributes the recovery to any release, and the 2025-08-26 'new update' predates Apple's published history.", "n/a", "1★-burst", "inside window 11 reviews, mean 2.82★, 6 1★ (54.5%, CI 28.0–78.7%); before 32 at 4.56★; after 28 at 4.61★", "none", "High-priority", "app-specific", ["13064284382", "13349206242", "13307114320"], "", "70-day window autumn 2025")

c(10, "§0.6; §0.6 tables (verbatim); §7.3; §0.11 #7", "insight", "Money complaints did not go away — they changed register: before v3.0 (2025-11-10) 7 of 43 (16.3%) money-negative at mean 1.57★ (1 of 7 rated 4–5★); from v3.0 on 7 of 28 (25.0%) at mean 3.86★ (4 of 7 rated 4–5★) (verbatim) " + table("## 0.6 Money complaints", 0) + " — before, a monetization complaint was a person leaving; after, a person staying and grumbling: 'Premium version is a little bit pricey, basic function still worth using it' (5★); 'oh the payments wall is hard would like to have more freebies or maybe ads instead of the payment wall' (5★); 'Good, but subscription required for almost all features' (5★). META_CONTRADICTION 3 (4.23%) 5★ whose text is a complaint, all about the paid tier (verbatim) " + table("## 0.6 Money complaints", 1) + "; 4 of 14 money-negative reviews are 5★ — the 5★ count overstates satisfaction, most in the latest quarter: 2026 Q3 has 5 money-negative of 9 (55.6%) at mean 4.44★.", "premium for most features", "mixed", "pre-v3.0 7/43 (16.3%, 1.57★); post 7/28 (25.0%, 3.86★); META_CONTRADICTION 3; 2026 Q3 55.6% money-neg at 4.44★", "none", "High-priority", "generalisable", ["14343374736", "14401503295", "14513739389", "13604788620"], "", "")

c(11, "§0.7; §0.7 table (verbatim); §0.11 #8", "must-never-break", "Reliability is not the problem — and stopped being one a year ago: 5 reviews (7.04%) report a defect, mean 2.80★, two blocking (verbatim) " + table("## 0.7 Reliability", 0) + " — the last defect report is 2025-08-26; the 37 reviews since contain none; Apple Health is the only subsystem with more than one failure ('the Apple Health connection has not worked', paid user 2★; 'the app crashes when adding Active Energy from apple health integration', 5★) and a third asks for more Health integration — wanted and, at least twice, broken.", "defects fixed by autumn 2025; Health integration flaky", "complaint", "5 / 7.04% / mean 2.80; 2 blocking; 0 in last 37 reviews / 12 months", "must-never-break", "High-priority", "generalisable", ["12339835181", "12552768633", "12579762746", "13063341493", "13064284382"], "", "")

c(12, "§0.8; §0.11 #6; §8.3", "must-have", "What people cannot work out: 4 reviews (5.63%) show a comprehension failure, mean 3.00★ — the momentum number itself ('I can't really tell on what basis momentum arises, or why it's good that it's displayed', kr 3★; 'At first I had some trouble following the points logic, but now that I've grasped it, I'm thrilled', de 5★ — same obstacle, two outcomes); the absence of a tick-mark ('Daily habits, tick mark not available', in 1★ — a 1★ caused by not finding the completion gesture); tracking in general ('the tracking part itself is a bit difficult for me personally', 3★). 'Removing the streak also removed the obvious scoreboard, and a minority cannot find the replacement.'", "momentum score unexplained in-product", "complaint", "4 / 5.63% / mean 3.00; one 1★", "must-have", "High-priority", "generalisable", ["12579762746", "12168189000", "13340807598", "14359876847"], "", "")

c(13, "§0.9 (frequency); §0.11 #4; §8.2", "feature", "'x times per week' scheduling is the only feature request made twice by otherwise-happy 4★ users, 11 months apart: 'una frecuencia concreta sin especificar el día (por ejemplo, 3 veces a la semana o 2 veces al mes)' (es 4★, 2025-05-07); ''x-mal pro Woche' zu definieren anstatt 'a Tag x und y'… Mich verwundert, dass es das nicht gibt' (de 4★, 2026-04-11) — still unaddressed at corpus end; scheduling is day-of-week only.", "absent: weekday-only scheduling", "complaint", "2 of 71 (both 4★), 11 months apart", "must-have", "Meaningful", "generalisable", ["12630919125", "13946139457"], "", "")

c(14, "§0.9 (widget); §0.11 #5; §2.3 widgets row; §8.2", "feature", "A multi-habit widget is the second repeated request: 'only able to select 1 habit to track at a time. So, I have to open the app to check which habits I have yet to complete' (us 5★); 'a widget what would show all Habbits at once' (be 4★); a per-habit widget exists and is praised ('Great widget too for each habit', pe 4★); one says widgets are paid ('You have to pay for widgets', pt 1★ — the whole review; single-source); 5 of 71 (7.04%) touch a widget gap, mean 3.80★.", "per-habit widget only; widgets reportedly paid", "complaint", "5 / 7.04% / mean 3.80; paid-widget 1★ n=1", "build-free", "High-priority", "generalisable", ["13429536002", "13839542276", "12300467429", "13277885578"], "", "")

c(15, "§0.10; §0.10 table (verbatim)", "data-caveat", "Eleven claims tested and not found (verbatim): " + table("## 0.10 Eleven claims", 0) + " — zero refund and zero cancellation mentions mean the churn analysis rests on a single review; zero privacy, support and accessibility complaints across 71 is a genuine if lightly-powered clean bill; the only ad mention asks for ads as a paywall alternative; the only account mention requests signup.", "no ads; no account", "mixed", "0 privacy, data loss, battery, support failure, accessibility, refund, cancellation, notification spam, login-wall", "none", "absence test", "generalisable", ["14401503295", "12234759445"], "", "")

c(16, "§0.11 #1, #2, #3, #4, #5, #6, #7, #8", "product-rule", "The eight decisions this corpus supports: 1) state the free limit in the description; 2) collapse the SKU catalogue and show periods; 3) settle the lifetime question publicly; 4) ship 'x times per week' scheduling; 5) ship a multi-habit widget and reconsider paywalling widgets; 6) explain the momentum number in-product; 7) do not treat the 5★ share as satisfaction (14 of 50 5★ content-free, 3 more complaints); 8) do not spend on reliability ahead of monetization clarity (0 defects in 37 reviews / 12 months; 7 money complaints in the same span).", "n/a", "mixed", "see §0", "product-rule", "High-priority", "generalisable", ["13349206242", "12652787691", "13946139457", "13429536002"], "", "")

c(17, "§1.8 table (verbatim); §1.8", "data-caveat", "Review integrity (verbatim): " + table("## 1.8 Review integrity", 0) + " — no burst (largest day 2 reviews; one same-day same-storefront pair in de checked and treated as coincidence); no solicitation pattern detectable, though the corpus is too small to rule one out; 3 rating-vs-text contradictions disclosed; one 5★ 'spam gamepasess, love from the dylano' coded META_NONSENSE and kept.", "n/a", "mixed", "0 repeat authors; 0 duplicates; 0 edited; 15 bodies <30 chars (21.1%)", "none", "method", "generalisable", ["14405189937", "12768970190", "12770144244"], "", "")

c(18, "§2.1 (named as missing)", "feature", "Named as missing by reviewers: iCloud sync / backup / account (2), dark mode, an Apple Watch app, 'x times per week' scheduling (2), a multi-habit widget (2), lock-screen widgets, habit sorting, multi-habit comparison graphs, a calendar completion view (2), more statistics and a social view.", "absent", "complaint", "mostly n=1; sync 2; frequency 2; multi-widget 2; calendar view 2", "research", "Meaningful", "generalisable", ["12234759445", "12756758711", "12630919125", "12292550440", "12529237684", "12300467429", "12579762746"], "", "")

c(19, "§2.1 (naming note)", "dont", "The product reaches users under many names: Store title 'Habit Tracker: Streak-Free', bundle 'Momentumly' (four reviewers call it Momentumly, one 'Streak Free'), and the paid tier under at least five names ('premium', 'Premium Abo', 'the pro subscription', 'premium plan', 'Momentumly Plus') while the listing sells under three — a search and support liability.", "inconsistent naming", "mixed", "5 names for the paid tier; 3 in the listing", "dont", "Meaningful", "generalisable", ["12863136997", "12893716000", "12905347299", "13809152355"], "", "")

c(20, "§2.2 bullets (description gaps); §2.2 version table (verbatim)", "dont", "The description states the concept well ('The first habit tracker without streaks') but never states a habit-count limit, names no price / tier / trial / one-time option, and does not mention widgets, Apple Health, the calendar, badges, the Habit Forest or iCloud — six capabilities reviewers discuss, two of which (widgets, Health) generated complaints. Version history (verbatim): " + table("## 2.2 The listed model", 2) + " — achievements predate the 'Badges & Achievements' release (a review mentions them 2025-08-15); the Habit Forest ('buying and planting a forest') exists only from v3.0.", "listing omits limits, prices and six features", "mixed", "25 release entries, 2 distinct announcements; 36 of 71 reviews predate the history", "dont", "external", "generalisable", ["13019604470", "14331668442"], "", "")

c(21, "§2.3 table (verbatim); §2.4", "monetization", "Free / paid / trial / unclear (verbatim): " + table("## 2.3 Free / paid / trial", 0) + " — no reviewer claims the app used to be free and became paid: the complaint is that the free tier is too thin, not that something was taken away; the earliest money complaint (2025-04-11) asks for a trial rather than alleging a change; no paywall-introduction event is visible.", "free: open + 1 habit; paid: 2nd habit, widgets (reported), 'most features', part of the Forest; no trial; lifetime contradicted; no ads", "mixed", "cap 3 sources; widgets paid n=1; trial 0 users; lifetime 3 conflicting", "undecided", "table", "app-specific", ["13259256224", "13349206242", "13277885578", "14513739389", "14359876847", "12530006457", "12552768633", "12652787691", "13941527190", "14331668442"], "", "")

c(22, "§2.3 (Habit Forest partly paid)", "monetization", "Gamification with a purchasable layer: the v3.0 Habit Forest — 'the bonus of buying and planting a forest' (us 5★) — acorns, a squirrel, foxes, achievements and badges; a Korean 3★ questions why the squirrel/acorns and the Focus tab exist.", "cosmetic reward layer, partly paid", "mixed", "n=1 praise; n=1 puzzled", "research", "limited evidence", "generalisable", ["14331668442", "12579762746", "14299453547"], "", "")

